{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "When the approximate timing of the need for leave is not foreseeable, an employee must provide notice to the employer as soon as practicable under the facts and circumstances of the particular case.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "references": null
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "When the approximate timing of the need for leave is not foreseeable, it generally should be practicable for the employee to provide notice of leave within the time prescribed by the employer's usual and customary notice requirements applicable to such leave.",
        "kind": "recommendation",
        "modality": "should",
        "modality_quote": "generally should",
        "references": ["§ 825.303(c)"]
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "When the approximate timing of the need for leave is not foreseeable, notice may be given by the employee's spokesperson (e.g., spouse, adult family member, or other responsible party) if the employee is unable to do so personally.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "references": null
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "If an employee's child has a severe asthma attack and the employee takes the child to the emergency room, the employee is not required to leave his or her child in order to report the absence while the child is receiving emergency treatment.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "would not be required",
        "references": null
      }
    },
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "If a child's asthma attack required only the use of an inhaler at home followed by a period of rest, the employee would be expected to call the employer promptly after ensuring the child has used the inhaler.",
        "kind": "recommendation",
        "modality": "should",
        "modality_quote": "would be expected to",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "An employee must provide sufficient information for an employer to reasonably determine whether the FMLA may apply to the leave request.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Depending on the situation, sufficient notice information may include that a condition renders the employee unable to perform the functions of the job; that the employee is pregnant or has been hospitalized overnight; whether the employee or the employee's family member is under the continuing care of a health care provider; if the leave is due to a qualifying exigency, that a military member is on covered active duty or call to covered active duty status (or has been notified of an impending call or order to covered active duty), that the requested leave is for one of the reasons listed in § 825.126(b), and the anticipated duration of the absence; or if the leave is for a family member that the condition renders the family member unable to perform daily activities or that the family member is a covered servicemember with a serious injury or illness; and the anticipated duration of the absence, if known.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may include",
        "references": ["§ 825.126(b)"]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "When an employee seeks leave for the first time for a FMLA-qualifying reason, the employee is not required to expressly assert rights under the FMLA or even mention the FMLA.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "need not",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "When an employee seeks leave due to a qualifying reason for which the employer has previously provided the employee FMLA-protected leave, the employee must specifically reference either the qualifying reason for leave or the need for FMLA leave.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "choice_text": "The employee must specifically reference at least one of two options: (1) the qualifying reason for leave, or (2) the need for FMLA leave.",
        "choice_quote": "F002",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Calling in “sick” without providing more information will not be considered sufficient notice to trigger an employer's obligations under the Act.",
        "kind": "statement",
        "modality": "not_stated",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "The employer will be expected to obtain any additional required information through informal means.",
        "kind": "recommendation",
        "modality": "should",
        "modality_quote": "will be expected to",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "An employee must respond to an employer's questions designed to determine whether an absence is potentially FMLA-qualifying.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "has an obligation to",
        "references": null
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Failure to respond to reasonable employer inquiries regarding the leave request may result in denial of FMLA protection if the employer is unable to determine whether the leave is FMLA-qualifying.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may",
        "references": null
      }
    },
    {
      "unit": "F003:F004",
      "unit_attributes": {
        "statement": "When the need for leave is not foreseeable, an employee must comply with the employer's usual and customary notice and procedural requirements for requesting leave, absent unusual circumstances.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "references": null
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "An employer may require employees to call a designated number or a specific individual to request leave.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "references": null
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "If an employee requires emergency medical treatment, he or she is not required to follow the employer's call-in procedure until his or her condition is stabilized and he or she has access to, and is able to use, a phone.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "would not be required",
        "references": null
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "In the case of an emergency requiring leave because of a FMLA-qualifying reason, written advance notice pursuant to an employer's internal rules and procedures may not be required when FMLA leave is involved.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may not be required",
        "references": null
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "If an employee does not comply with the employer's usual notice and procedural requirements, and no unusual circumstances justify the failure to comply, FMLA-protected leave may be delayed or denied.",
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may",
        "references": null
      }
    }
  ]
}
